"""The NEPO program: blocks, variables, functions and the main program, read from the Lab's XML (export or program XML).

    program = NepoProgram.from_file('clap_counter.xml')
    program.variables       [Variable('claps', 'Number', 0, block), ...]
    program.functions       {'clampSpeed': Function(...), ...}
    program.main            the statement blocks connected to the start block
    program.block('cc12')   any block by its id
    program.describe()      a JSON-able summary, including test hints (see summary.py)
"""

import re
import xml.etree.ElementTree as ET

NS = '{http://de.fhg.iais.roberta.blockly}'

# block types whose code the Edison generator emits as a statement that "does something" on the robot
ACTION_TYPES = frozenset([
    'actions_led_edison', 'robActions_motorDiff_on', 'robActions_motorDiff_on_for', 'robActions_motorDiff_turn',
    'robActions_motorDiff_turn_for', 'robActions_motorDiff_curve', 'robActions_motorDiff_curve_for', 'robActions_motorDiff_stop',
    'robActions_motor_on', 'robActions_motor_stop', 'robActions_play_tone', 'mbedActions_play_note', 'robActions_play_file',
    'edisonCommunication_ir_sendBlock', 'robControls_wait_time', 'robControls_wait_for', 'edisonSensors_sensor_reset',
])
SENSOR_TYPES = frozenset([
    'robSensors_key_getSample', 'robSensors_infrared_getSample', 'robSensors_light_getSample', 'robSensors_sound_getSample',
    'robSensors_irseeker_getSample', 'robSensors_getSample', 'edisonCommunication_ir_receiveBlock',
])
FUNCTION_DEF_TYPES = frozenset(['robProcedures_defnoreturn', 'robProcedures_defreturn'])
FUNCTION_CALL_TYPES = frozenset(['robProcedures_callnoreturn', 'robProcedures_callreturn'])


def _tag(el):
    return el.tag[len(NS):] if el.tag.startswith(NS) else el.tag


class Block(object):
    """One NEPO block. fields: {name: text}; values: {input name: Block}; statements: {input name: [Block]}."""

    def __init__(self, el, parent=None, parent_input=None):
        self.id = el.get('id')
        self.type = el.get('type')
        self.in_task = el.get('intask') != 'false'
        self.disabled = el.get('disabled') == 'true'
        self.parent = parent
        self.parent_input = parent_input
        self.fields = {}
        self.values = {}
        self.statements = {}
        self.mutation = {}
        self.mutation_args = []
        self.errors = []
        self.warnings = []
        for child in _flatten(el):
            tag = _tag(child)
            if tag == 'field':
                self.fields[child.get('name')] = (child.text or '').strip()
            elif tag == 'mutation':
                self.mutation = dict(child.attrib)
                self.mutation_args = [dict(a.attrib) for a in child if _tag(a) == 'arg']
            elif tag == 'value':
                blocks = [b for b in child if _tag(b) == 'block']
                if blocks:
                    self.values[child.get('name')] = Block(blocks[0], self, child.get('name'))
            elif tag == 'statement':
                self.statements[child.get('name')] = [Block(b, self, child.get('name')) for b in child if _tag(b) == 'block']
            elif tag == 'error':
                self.errors.append((child.text or '').strip())
            elif tag == 'warning':
                self.warnings.append((child.text or '').strip())

    def children(self):
        for b in self.values.values():
            yield b
        for seq in self.statements.values():
            for b in seq:
                yield b

    def walk(self):
        yield self
        for c in self.children():
            for d in c.walk():
                yield d

    @property
    def generated(self):
        """False if the generator skips the block (disabled, or not connected to the program)."""
        b = self
        while b is not None:
            if b.disabled or not b.in_task:
                return False
            b = b.parent
        return True

    def literal(self):
        """The value of a literal block (number, boolean, list of literals), else None."""
        if self.type in ('math_number', 'math_integer'):
            text = self.fields.get('NUM', '')
            try:
                value = float(text)
            except ValueError:
                return None
            return int(value) if value == int(value) else value
        if self.type == 'logic_boolean':
            return self.fields.get('BOOL') == 'TRUE'
        if self.type == 'robLists_create_with':
            items = [self.values.get('ADD%d' % i) for i in range(int(self.mutation.get('items', 0)))]
            values = [b.literal() if b is not None else None for b in items]
            return values if None not in values else None
        return None

    def __repr__(self):
        return '<Block %s %s>' % (self.type, self.id)


def _flatten(el):
    # robProcedures_defreturn wraps its inputs in <repetitions>
    for child in el:
        if _tag(child) == 'repetitions':
            for c in child:
                yield c
        else:
            yield child


class Variable(object):
    def __init__(self, name, type_, initial, block):
        self.name, self.type, self.initial, self.block = name, type_, initial, block

    def __repr__(self):
        return 'Variable(%r, %r, %r)' % (self.name, self.type, self.initial)


class Function(object):
    def __init__(self, block):
        self.block = block
        self.name = block.fields.get('NAME')
        self.params = [(p.fields.get('VAR'), p.fields.get('TYPE')) for p in block.statements.get('ST', [])]
        self.returns = block.fields.get('TYPE') if block.type == 'robProcedures_defreturn' else None
        self.body = block.statements.get('STACK', [])
        self.return_block = block.values.get('RETURN')

    def __repr__(self):
        return 'Function(%s(%s) -> %s)' % (self.name, ', '.join('%s: %s' % p for p in self.params), self.returns)


class NepoProgram(object):
    def __init__(self, xml_text):
        self.xml = xml_text
        program_xml = _program_part(xml_text)
        root = ET.fromstring(program_xml)
        self.robot_group = root.get('robottype')
        self.instances = []  # each: list of top-level blocks (a chain)
        for inst in root:
            if _tag(inst) == 'instance':
                self.instances.append([Block(b) for b in inst if _tag(b) == 'block'])
        self._blocks = {}
        for chain in self.instances:
            for top in chain:
                for b in top.walk():
                    self._blocks[b.id] = b
        self.start = None
        self.main = []
        self.functions = {}
        for chain in self.instances:
            if chain and chain[0].type == 'robControls_start':
                self.start, self.main = chain[0], chain[1:]
            for top in chain:
                if top.type in FUNCTION_DEF_TYPES and top.generated:
                    f = Function(top)
                    self.functions[f.name] = f
        self.variables = []
        if self.start is not None:
            for decl in self.start.statements.get('ST', []):
                initial = decl.values.get('VALUE')
                self.variables.append(Variable(decl.fields.get('VAR'), decl.fields.get('TYPE'),
                                               initial.literal() if initial is not None else None, decl))
        # parent links for top-level chains: blocks after the first in a chain have no XML parent, but belong to it
        self._owner = {}
        for chain in self.instances:
            for top in chain:
                owner = top.fields.get('NAME') if top.type in FUNCTION_DEF_TYPES else None
                for b in top.walk():
                    self._owner[b.id] = owner

    @classmethod
    def from_file(cls, path):
        with open(path, encoding='utf-8') as f:
            return cls(f.read())

    @property
    def blocks(self):
        return dict(self._blocks)

    def block(self, block_id):
        return self._blocks.get(block_id)

    def function_of(self, block_id):
        """The name of the NEPO function a block belongs to, or None for the main program."""
        return self._owner.get(block_id)

    def generated_blocks(self):
        return [b for b in self._blocks.values() if b.generated]

    def errors(self):
        """[(block, message)] of the Lab's annotations, if the XML came back from the Lab."""
        return [(b, e) for b in self._blocks.values() for e in b.errors]

    def describe(self):
        from .summary import describe
        return describe(self)


def _program_part(xml_text):
    """The <block_set> of the program: from an export (<export><program>...</program><config>...) or as is."""
    m = re.search(r'<program>\s*(.*?)\s*</program>', xml_text, re.S)
    return m.group(1) if m else xml_text.strip()


def config_part(xml_text):
    m = re.search(r'<config>\s*(.*?)\s*</config>', xml_text, re.S)
    return m.group(1) if m else None

files.nepotest/observer.py:
"""Watches a run of the generated EdPy and translates it back to NEPO.

The engine calls the observer before every statement (instrumented code) and at every Ed call (with the calling
frame). With the Lab's source map, the observer knows for each statement and each Ed call which block's code it is:
- block executions: a statement that starts the code of a block starts an execution of that block
- Ed calls are attributed to all blocks whose code contains the call site (for calls made inside a generated helper
  function such as _diffDrive, the call site of the helper, and the helper's arguments are kept: the NEPO values)
- NEPO functions (____name) are wrapped, so their calls, arguments and results are recorded
From that it derives the NEPO-level actions (decode_action) and the block coverage (coverage).
"""

from .engine.containers import EdList, TuneString
from .engine.program import instruction_position
from .nepo import ACTION_TYPES, FUNCTION_DEF_TYPES

NOT_COVERABLE = frozenset(['text_comment'])


def nepo_value(v):
    if isinstance(v, EdList):
        return v.to_list()
    if isinstance(v, TuneString):
        return v.text()
    return v


class Execution(object):
    """One execution of one block: when it started, which Ed calls (trace indices) and helper calls it made."""

    def __init__(self, index, t, block_id, block_type):
        self.index, self.t, self.block_id, self.type = index, t, block_id, block_type
        self.calls = []
        self.helpers = []  # (helper name, {param: NEPO value}), e.g. ('_diffDrive', {'direction': 1, 'speed': 150, 'distance': 10})


class FunctionCall(object):
    def __init__(self, name, args, t, depth):
        self.name, self.args, self.t, self.depth = name, args, t, depth
        self.returned = None
        self.t_end = None
        self.completed = False

    def to_json(self):
        return {'function': self.name, 'args': self.args, 'returned': self.returned, 't': self.t, 't_end': self.t_end,
                'completed': self.completed}


class Observer(object):
    def __init__(self, subject, robot):
        self.subject = subject
        self.robot = robot
        self.sm = subject.source_map
        self.filename = subject.edprogram.filename
        self.statements = []  # (start, end, block at start, starts that block?)
        for (line, end_line, col, end_col) in subject.edprogram.statements:
            s, e = self.sm.offset(line, col), self.sm.offset(end_line, end_col)
            spanning = self.sm.blocks_spanning(s, e)
            b = spanning[0] if spanning else None
            starts = b is not None and self.sm.start(b) == s and self.sm.type_of(b) not in FUNCTION_DEF_TYPES
            self.statements.append((s, e, b, starts))
        self.executed = set()
        self.executions = []
        self.current = {}
        self.call_blocks = {}
        self.function_calls = []
        self._depth = 0
        self.main_ran = False

    # ------------------------------------------------------------------ engine listener interface

    def on_statement(self, index):
        self.executed.add(index)
        _, _, block_id, starts = self.statements[index]
        if starts:
            ex = Execution(len(self.executions), self.robot.now, block_id, self.sm.type_of(block_id))
            self.executions.append(ex)
            self.current[block_id] = ex

    def on_ed_call(self, index, frame):
        helper = None
        blocks = []
        f = frame
        while f is not None:
            code = f.f_code
            if code.co_filename == self.filename:
                blocks = self.sm.at_position(instruction_position(code, f.f_lasti))
                if blocks:
                    break
                if code.co_name != '<module>' and not code.co_name.startswith('____'):
                    params = code.co_varnames[:code.co_argcount]
                    helper = (code.co_name, dict((p, nepo_value(f.f_locals.get(p))) for p in params))
            f = f.f_back
        self.call_blocks[index] = blocks
        for b in blocks:
            ex = self.current.get(b)
            if ex is not None:
                ex.calls.append(index)
                if helper is not None:
                    ex.helpers.append(helper)

    def on_prelude_done(self, namespace):
        for name in list(namespace):
            if name.startswith('____') and callable(namespace[name]):
                namespace[name] = self._wrap(name[4:], namespace[name])

    def _wrap(self, nepo_name, fn):
        observer = self

        def nepo_function(*args):
            call = FunctionCall(nepo_name, [nepo_value(a) for a in args], observer.robot.now, observer._depth)
            observer.function_calls.append(call)
            observer._depth += 1
            try:
                result = fn(*args)
            finally:
                observer._depth -= 1
                call.t_end = observer.robot.now
            call.returned = nepo_value(result)
            call.completed = True
            return result

        nepo_function.__name__ = fn.__name__
        return nepo_function

    # ------------------------------------------------------------------ results

    def actions(self):
        """NEPO-level actions: one dict per execution of an action block, in execution order."""
        result = []
        trace = self.robot.trace
        for ex in self.executions:
            if ex.type in ACTION_TYPES:
                result.append(decode_action(ex, self.subject.nepo.block(ex.block_id), trace, self.subject.nepo))
        return result

    def sensor_reads(self):
        """{block id: {'type', 'reads', 'values'}} for sensor blocks that read the robot"""
        reads = {}
        for index, blocks in self.call_blocks.items():
            for b in blocks:
                t = self.sm.type_of(b)
                if t and (t.startswith('robSensors_') or t == 'edisonCommunication_ir_receiveBlock'):
                    r = reads.setdefault(b, {'type': t, 'reads': 0, 'values': {}})
                    r['reads'] += 1
                    v = self.robot.trace[index].result
                    r['values'][str(v)] = r['values'].get(str(v), 0) + 1
                    break
        return reads

    def covered_blocks(self):
        covered = set()
        for index in self.executed:
            s, e, b, _ = self.statements[index]
            for block_id in self.sm.blocks_spanning(s, e):
                if self.sm.type_of(block_id) not in FUNCTION_DEF_TYPES:
                    covered.add(block_id)
        for blocks in self.call_blocks.values():
            covered.update(b for b in blocks if self.sm.type_of(b) not in FUNCTION_DEF_TYPES)
        # expression blocks: covered, if the innermost statement that contains their start was executed
        for block_id in self.sm.blocks:
            enclosing = self.subject.enclosing_statement(block_id)
            if enclosing is not None and enclosing in self.executed and self.sm.type_of(block_id) not in FUNCTION_DEF_TYPES:
                covered.add(block_id)
        called = set(c.name for c in self.function_calls)
        for f in self.subject.nepo.functions.values():
            if f.name in called:
                covered.add(f.block.id)
        start = self.subject.nepo.start
        if start is not None and self.main_ran:
            covered.add(start.id)
        return covered


def _field(block, name, default=None):
    return block.fields.get(name, default) if block is not None else default


def _helper(ex, name):
    for helper_name, params in ex.helpers:
        if helper_name == name:
            return params
    return {}


def _ed_calls(ex, trace, name):
    return [trace[i] for i in ex.calls if trace[i].name == name]


# the kind of an action, independent of the block variant (a drive with and without distance is both a 'drive')
ACTION_KINDS = {
    'actions_led_edison': 'led', 'robActions_motorDiff_on': 'drive', 'robActions_motorDiff_on_for': 'drive',
    'robActions_motorDiff_turn': 'turn', 'robActions_motorDiff_turn_for': 'turn', 'robActions_motorDiff_curve': 'curve',
    'robActions_motorDiff_curve_for': 'curve', 'robActions_motorDiff_stop': 'stop', 'robActions_motor_stop': 'stop',
    'robActions_motor_on': 'motor', 'robActions_play_tone': 'tone', 'mbedActions_play_note': 'tone',
    'robActions_play_file': 'sound_file', 'edisonCommunication_ir_sendBlock': 'ir_send', 'robControls_wait_time': 'wait',
    'robControls_wait_for': 'wait_for', 'edisonSensors_sensor_reset': 'sensor_reset',
}
# normalized directions: the XML spells them FOREWARD, BACKWARD or BACKWARDS, RIGHT, LEFT
DIRECTIONS = {'FOREWARD': 'forward', 'FORWARD': 'forward', 'BACKWARD': 'backward', 'BACKWARDS': 'backward', 'RIGHT': 'right', 'LEFT': 'left'}


def decode_action(ex, block, trace, nepo):
    """the NEPO view of one execution of an action block"""
    a = {'t': ex.t, 'block': ex.type, 'block_id': ex.block_id, 'function': nepo.function_of(ex.block_id),
         'action': ACTION_KINDS.get(ex.type, ex.type)}
    t = ex.type
    if t == 'actions_led_edison':
        a.update(port=_field(block, 'ACTORPORT'), mode=_field(block, 'MODE'))
    elif t in ('robActions_motorDiff_on', 'robActions_motorDiff_on_for'):
        h = _helper(ex, '_diffDrive')
        a.update(direction=_field(block, 'DIRECTION'), power=h.get('speed'))
        if t.endswith('_for'):
            a['distance_cm'] = h.get('distance')
    elif t in ('robActions_motorDiff_turn', 'robActions_motorDiff_turn_for'):
        h = _helper(ex, '_diffTurn')
        a.update(direction=_field(block, 'DIRECTION'), power=h.get('speed'))
        if t.endswith('_for'):
            a['degrees'] = h.get('degree')
    elif t in ('robActions_motorDiff_curve', 'robActions_motorDiff_curve_for'):
        h = _helper(ex, '_diffCurve')
        a.update(direction=_field(block, 'DIRECTION'), power_left=h.get('leftSpeed'), power_right=h.get('rightSpeed'))
        if t.endswith('_for'):
            a['distance_cm'] = h.get('distance')
    elif t == 'robActions_motor_on':
        h = _helper(ex, '_motorOn')
        a.update(port=_field(block, 'MOTORPORT'), power=h.get('power'))
    elif t == 'robActions_motor_stop':
        a.update(port=_field(block, 'MOTORPORT'))
    elif t == 'robActions_play_tone':
        tones = _ed_calls(ex, trace, 'PlayTone')
        freq = block.values.get('FREQUENCE').literal() if block is not None and 'FREQUENCE' in block.values else None
        if freq is None and tones and tones[0].args[0]:
            freq = round(8000000.0 / tones[0].args[0])  # the generator emits Ed.PlayTone(8000000/f, ms)
        a.update(frequency_hz=freq, duration_ms=tones[0].args[1] if tones else None)
    elif t == 'mbedActions_play_note':
        a.update(frequency_hz=float(_field(block, 'FREQUENCE', 0)), duration_ms=int(float(_field(block, 'DURATION', 0))))
    elif t == 'robActions_play_file':
        a.update(file=int(_field(block, 'FILE', 0)))
    elif t == 'edisonCommunication_ir_sendBlock':
        a.update(value=_helper(ex, '_irSend').get('payload'))
    elif t == 'robControls_wait_time':
        waits = _ed_calls(ex, trace, 'TimeWait')
        a.update(ms=waits[0].args[0] if waits else None)
    elif t == 'robControls_wait_for':
        a.update(t_end=trace[ex.calls[-1]].t if ex.calls else None)
    elif t == 'edisonSensors_sensor_reset':
        a.update(sensor=_field(block, 'SENSOR'))
    if 'direction' in a:
        a['dir'] = DIRECTIONS.get(a['direction'], a['direction'])
    return a

files.nepotest/sourcemap.py:
"""The source map of the Lab (REST /projectWorkflow/sourceForTest): for every block, the char ranges of its EdPy code.

Offsets are chars of the EdPy source (the Lab counts Java UTF-16 units; identical for everything but characters outside
the Basic Multilingual Plane). CPython positions use UTF-8 byte columns; offset() converts them.
"""


class SourceMap(object):
    def __init__(self, source, data):
        self.source = source
        self.blocks = {}  # id -> (type, [(start, end)])
        for block_id, info in (data or {}).get('blocks', {}).items():
            ranges = [(max(0, s), min(len(source), e)) for s, e in info.get('ranges', [])]
            ranges = [(s, e) for s, e in ranges if s < e]
            if ranges:
                self.blocks[block_id] = (info.get('type'), ranges)
        self._line_starts = [0]
        for i, ch in enumerate(source):
            if ch == '\n':
                self._line_starts.append(i + 1)
        self._lines = source.split('\n')
        # innermost first: sorted by range length
        self._by_size = sorted(((e - s, s, e, b) for b, (_, rs) in self.blocks.items() for s, e in rs))

    def offset(self, lineno, col_utf8):
        """char offset of a CPython position (1-based line, UTF-8 byte column)"""
        if lineno is None or not 1 <= lineno <= len(self._line_starts):
            return None
        line = self._lines[lineno - 1]
        col = len(line.encode('utf-8')[:col_utf8].decode('utf-8', 'ignore')) if col_utf8 else 0
        return self._line_starts[lineno - 1] + col

    def blocks_at(self, offset):
        """ids of all blocks whose code contains the offset, innermost first"""
        if offset is None:
            return []
        seen, result = set(), []
        for _, s, e, b in self._by_size:
            if s <= offset < e and b not in seen:
                seen.add(b)
                result.append(b)
        return result

    def blocks_spanning(self, start, end):
        """ids of all blocks whose code contains all of [start, end), innermost first"""
        if start is None:
            return []
        if end is None or end <= start:
            return self.blocks_at(start)
        seen, result = set(), []
        for _, s, e, b in self._by_size:
            if s <= start and end <= e and b not in seen:
                seen.add(b)
                result.append(b)
        return result

    def at_position(self, position):
        """blocks spanning a CPython position (lineno, end_lineno, col_offset, end_col_offset), innermost first"""
        if position is None:
            return []
        return self.blocks_spanning(self.offset(position[0], position[2]), self.offset(position[1], position[3]))

    def innermost(self, offset):
        found = self.blocks_at(offset)
        return found[0] if found else None

    def start(self, block_id):
        return min(s for s, _ in self.blocks[block_id][1]) if block_id in self.blocks else None

    def type_of(self, block_id):
        return self.blocks[block_id][0] if block_id in self.blocks else None

    def text(self, block_id):
        return [self.source[s:e] for s, e in self.blocks.get(block_id, (None, []))[1]]

    def line_of(self, block_id):
        s = self.start(block_id)
        if s is None:
            return None
        return self.source.count('\n', 0, s) + 1

files.nepotest/spec.py:
"""Declarative tests for NEPO programs (JSON), and their runner. Made for learners' test editors and AI test generators:
a test file is data, can be validated before it runs (validate_spec, schema/nepo-tests.schema.json), and never executes
code of its own. See docs/ai/nepo-unit-testing.md for the full reference.

    {"format": "nepotest", "version": 1, "program": "clap_counter.xml", "bundle": "clap_counter.bundle.json",
     "tests": [
       {"name": "speed is clamped", "call": "clampSpeed", "args": [150], "expect": {"returns": 100}},
       {"name": "three claps", "world": [{"event": "clap", "at": 1000}, ...], "max_time_ms": 10000,
        "expect": {"status": "finished", "variables": {"claps": 3},
                   "actions": [{"block": "robActions_motorDiff_on_for", "power": 100, "distance_cm": 10}]}}]}
"""

import json
import os

from .world import EVENTS, World

EXPECT_KEYS = ('returns', 'status', 'finished_within_ms', 'variables', 'actions', 'actions_exactly', 'no_actions',
               'action_count', 'calls', 'error', 'covers')
TEST_KEYS = ('name', 'description', 'call', 'args', 'globals', 'world', 'max_time_ms', 'max_steps', 'expect', 'origin', 'block_id')
STATUS_VALUES = ('finished', 'running', 'time_limit', 'step_limit')


# ---------------------------------------------------------------------- validation

def validate_spec(spec, subject=None):
    """[problem] for a test file (dict); empty if it's valid. With a subject, function and variable names are checked too."""
    problems = []
    if not isinstance(spec, dict) or spec.get('format') != 'nepotest':
        return ['not a nepotest file: "format" must be "nepotest"']
    if not isinstance(spec.get('tests'), list) or not spec['tests']:
        problems.append('"tests" must be a non-empty list')
        return problems
    names = set()
    for i, test in enumerate(spec['tests']):
        where = 'tests[%d]' % i
        if not isinstance(test, dict):
            problems.append('%s must be an object' % where)
            continue
        for key in test:
            if key not in TEST_KEYS:
                problems.append('%s: unknown key %r' % (where, key))
        name = test.get('name')
        if not isinstance(name, str) or not name:
            problems.append('%s: "name" is required' % where)
        elif name in names:
            problems.append('%s: duplicate name %r' % (where, name))
        names.add(name)
        expect = test.get('expect')
        if not isinstance(expect, dict) or not expect:
            problems.append('%s: "expect" must be a non-empty object' % where)
            expect = {}
        for key in expect:
            if key not in EXPECT_KEYS:
                problems.append('%s.expect: unknown key %r (known: %s)' % (where, key, ', '.join(EXPECT_KEYS)))
        is_call = 'call' in test
        if is_call and 'status' in expect:
            problems.append('%s.expect.status only applies to program runs, not to calls' % where)
        if not is_call and ('returns' in expect or 'args' in test or 'globals' in test):
            problems.append('%s: "returns", "args" and "globals" need "call"' % where)
        if expect.get('status') is not None and expect['status'] not in STATUS_VALUES:
            problems.append('%s.expect.status must be one of %s' % (where, ', '.join(STATUS_VALUES)))
        try:
            World(test.get('world') or [])
        except (ValueError, TypeError, AttributeError) as e:
            problems.append('%s.world: %s (events: %s)' % (where, e, ', '.join(EVENTS)))
        if subject is not None:
            if is_call and test['call'] not in subject.nepo.functions:
                problems.append('%s: the program has no function %r (it has: %s)' % (where, test['call'], ', '.join(subject.nepo.functions) or 'none'))
            elif is_call and len(test.get('args', [])) != len(subject.nepo.functions[test['call']].params):
                problems.append('%s: %s takes %d arguments' % (where, test['call'], len(subject.nepo.functions[test['call']].params)))
            declared = set(v.name for v in subject.nepo.variables)
            for var in list((test.get('globals') or {})) + list((expect.get('variables') or {})):
                if var not in declared:
                    problems.append('%s: the program has no variable %r (it has: %s)' % (where, var, ', '.join(sorted(declared)) or 'none'))
    return problems


# ---------------------------------------------------------------------- matching

def _value_matches(expected, actual):
    if isinstance(expected, dict) and 'not' in expected:
        return not _value_matches(expected['not'], actual)
    if isinstance(expected, dict) and ('min' in expected or 'max' in expected):
        return isinstance(actual, (int, float)) and not isinstance(actual, bool) and \
            expected.get('min', actual) <= actual <= expected.get('max', actual)
    if isinstance(expected, dict) and 'approx' in expected:
        return isinstance(actual, (int, float)) and abs(actual - expected['approx']) <= expected.get('tol', 1e-6)
    if isinstance(expected, bool) or isinstance(actual, bool):
        return expected is actual or (isinstance(expected, bool) and isinstance(actual, bool) and expected == actual)
    if isinstance(expected, (int, float)) and isinstance(actual, (int, float)):
        return abs(expected - actual) < 1e-9
    return expected == actual


def matches(matcher, item):
    return all(k in item and _value_matches(v, item[k]) for k, v in matcher.items())


def _in_order(matchers, items):
    """index of the first matcher that can't be found (in order, gaps allowed), or None"""
    pos = 0
    for i, m in enumerate(matchers):
        while pos < len(items) and not matches(m, items[pos]):
            pos += 1
        if pos == len(items):
            return i
        pos += 1
    return None


def _compact(items, limit=12):
    shown = [dict((k, v) for k, v in a.items() if k not in ('block_id',)) for a in items[:limit]]
    return shown + (['... %d more' % (len(items) - limit)] if len(items) > limit else [])


def check_expectations(expect, test, result, is_call):
    failures = []

    def fail(key, expected, actual, message=None):
        failures.append({'expect': key, 'expected': expected, 'actual': actual, 'message': message})

    error_expected = expect.get('error')
    if result.error is not None:
        e = result.error.to_json()
        if error_expected is None:
            fail('error', None, e, 'the program failed: %s' % result.error)
        elif error_expected == 'any':
            pass
        elif isinstance(error_expected, str) and error_expected != e['kind']:
            fail('error', error_expected, e)
        elif isinstance(error_expected, dict) and not matches(error_expected, e):
            fail('error', error_expected, e)
    elif error_expected is not None:
        fail('error', error_expected, None, 'the program did not fail')
    if 'returns' in expect and result.error is None and not _value_matches(expect['returns'], result._returned):
        fail('returns', expect['returns'], result._returned)
    if not is_call:
        status = expect.get('status')
        if status == 'running' and not result.running:
            fail('status', 'running', result.status)
        elif status in ('finished', 'time_limit', 'step_limit') and result.status != status:
            fail('status', status, result.status)
        if 'finished_within_ms' in expect and not (result.finished and result.time_ms <= expect['finished_within_ms']):
            fail('finished_within_ms', expect['finished_within_ms'], {'status': result.status, 'time_ms': result.time_ms})
    for name, value in (expect.get('variables') or {}).items():
        if name not in result.variables or not _value_matches(value, result.variables[name]):
            fail('variables.%s' % name, value, result.variables.get(name))
    if 'actions' in expect:
        missing = _in_order(expect['actions'], result.actions)
        if missing is not None:
            fail('actions[%d]' % missing, expect['actions'][missing], _compact(result.actions),
                 'not found in this order among the actions')
    if 'actions_exactly' in expect:
        exp = expect['actions_exactly']
        if len(exp) != len(result.actions) or not all(matches(m, a) for m, a in zip(exp, result.actions)):
            fail('actions_exactly', exp, _compact(result.actions, 40))
    for i, m in enumerate(expect.get('no_actions') or []):
        hits = [a for a in result.actions if matches(m, a)]
        if hits:
            fail('no_actions[%d]' % i, m, _compact(hits), 'this action happened')
    counts = expect.get('action_count') or {}
    if isinstance(counts, dict):  # {"<block type>": n}
        counts = [{'match': {'block': block_type}, 'count': n} for block_type, n in counts.items()]
    for i, c in enumerate(counts):  # [{"match": matcher, "count": n}]
        actual = sum(1 for a in result.actions if matches(c['match'], a))
        if not _value_matches(c['count'], actual):
            fail('action_count[%d]' % i, c, actual, 'actions matching %s happened %d times' % (json.dumps(c['match']), actual))
    if 'calls' in expect:
        calls = [dict(c, **({'returns': c['returned']} if c['completed'] else {})) for c in result.calls]
        missing = _in_order(expect['calls'], calls)
        if missing is not None:
            fail('calls[%d]' % missing, expect['calls'][missing], _compact(calls), 'not found in this order among the function calls')
    for block_id in expect.get('covers') or []:
        if block_id not in result.coverage.covered:
            fail('covers', block_id, None, 'block %s was not executed' % block_id)
    return failures


# ---------------------------------------------------------------------- running

def run_test(subject, test, defaults=None):
    options = dict(defaults or {})
    options.update(dict((k, test[k]) for k in ('max_time_ms', 'max_steps') if k in test))
    world = World(test.get('world') or [])
    is_call = 'call' in test
    if is_call:
        result = subject.call(test['call'], *test.get('args', []), globals=test.get('globals'), world=world,
                              max_steps=options.get('max_steps', 100000), max_time_ms=options.get('max_time_ms', 60000))
    else:
        result = subject.run(world, max_time_ms=options.get('max_time_ms', 60000), max_steps=options.get('max_steps', 2000000))
    failures = check_expectations(test['expect'], test, result, is_call)
    report = {'name': test['name'], 'block_id': test.get('block_id'), 'outcome': 'failed' if failures else 'passed', 'failures': failures,
              'error': result.error.to_json() if result.error else None, 'time_ms': result.time_ms,
              'variables': result.variables, 'actions': result.actions, 'calls': result.calls,
              'covered_blocks': sorted(result.coverage.covered)}
    if is_call:
        report['returned'] = result._returned
    else:
        report['status'] = result.status
    return report, result.coverage


def run_spec(spec, subject):
    """Runs all tests of a validated test file against a TestSubject. Returns the results (JSON-able dict)."""
    reports, coverage = [], None
    for test in spec['tests']:
        try:
            report, cov = run_test(subject, test, spec.get('defaults'))
            coverage = cov if coverage is None else coverage.merge(cov)
        except Exception as e:  # a problem of the test, not of the program (e.g. wrong argument types)
            report = {'name': test.get('name'), 'block_id': test.get('block_id'), 'outcome': 'error', 'failures': [],
                      'error': {'kind': 'test_error', 'message': '%s: %s' % (type(e).__name__, e)}}
        reports.append(report)
    counts = dict((o, sum(1 for r in reports if r['outcome'] == o)) for o in ('passed', 'failed', 'error'))
    return {'format': 'nepotest-results', 'version': 1, 'program': spec.get('program'), 'summary': counts,
            'coverage': coverage.to_json() if coverage is not None else None, 'tests': reports}


def load_spec(path):
    with open(path, encoding='utf-8') as f:
        spec = json.load(f)
    spec['_dir'] = os.path.dirname(os.path.abspath(path))
    return spec


def subject_for(spec, lab=None):
    """the TestSubject of a test file: its program, converted by the Lab or taken from its bundle"""
    from .subject import TestSubject
    base = spec.get('_dir', '.')
    program = os.path.join(base, spec['program'])
    bundle = os.path.join(base, spec['bundle']) if spec.get('bundle') else None
    return TestSubject.load(program, lab=lab, bundle=bundle)

files.nepotest/subject.py:
"""A NEPO program under test: converted by the Lab, run on the engine, observed in NEPO terms.

    subject = TestSubject.load('clap_counter.xml', lab='http://localhost:1999')    # or bundle='...bundle.json'
    result = subject.call('clampSpeed', 150)          # a NEPO function, in isolation
    result.returned == 100
    run = subject.run(World().clap(1000).clap(2000).clap(3000))
    run.finished, run.variables['claps'], run.actions, run.calls, run.coverage, run.error
"""

import os
import sys

from .engine import EdProgram, EdTestError, StepLimitExceeded
from .engine.program import instruction_position  # noqa: F401  (re-exported for tools)
from .lab import Bundle, LabClient
from .nepo import NepoProgram
from .observer import Observer, nepo_value
from .sourcemap import SourceMap
from .world import World



class ConversionError(Exception):
    """The Lab didn't convert the program, usually because of block errors (block_errors: [(block_id, type, key)])."""

    def __init__(self, bundle):
        self.bundle = bundle
        self.block_errors = []
        if bundle.annotated_xml:
            try:
                annotated = NepoProgram(bundle.annotated_xml)
                self.block_errors = [(b.id, b.type, e) for b, e in annotated.errors()]
            except Exception:
                pass
        detail = ', '.join('%s (block %s %s)' % (e, t, i) for i, t, e in self.block_errors) or bundle.message
        super(ConversionError, self).__init__('the Lab did not convert the program: %s' % detail)


class NepoError(Exception):
    """A runtime problem of the program, attributed to a block.

    kind: 'overflow', 'division_by_zero', 'index_out_of_range', 'negative_value', 'recursion', ... (engine error kinds)"""

    def __init__(self, kind, message, block_id=None, block_type=None, function=None, edpy_line=None):
        super(NepoError, self).__init__(message)
        self.kind, self.message = kind, message
        self.block_id, self.block_type, self.function, self.edpy_line = block_id, block_type, function, edpy_line

    def to_json(self):
        return {'kind': self.kind, 'message': self.message, 'block_id': self.block_id, 'block_type': self.block_type,
                'function': self.function, 'edpy_line': self.edpy_line}

    def __str__(self):
        where = ' in block %s (%s)' % (self.block_id, self.block_type) if self.block_id else ''
        if self.function:
            where += ' of function %s' % self.function
        return '%s%s' % (self.message, where)


class Coverage(object):
    def __init__(self, subject, covered):
        self.subject = subject
        self.coverable = subject.coverable_blocks()
        self.covered = set(covered) & self.coverable

    def merge(self, other):
        return Coverage(self.subject, self.covered | other.covered)

    @property
    def uncovered(self):
        return sorted(self.coverable - self.covered, key=lambda b: self.subject.source_map.start(b))

    @property
    def ratio(self):
        return len(self.covered) / float(len(self.coverable)) if self.coverable else 1.0

    def to_json(self):
        nepo = self.subject.nepo
        return {'blocks_total': len(self.coverable), 'blocks_covered': len(self.covered), 'ratio': round(self.ratio, 3),
                'uncovered': [{'block_id': b, 'type': self.subject.source_map.type_of(b), 'function': nepo.function_of(b)}
                              for b in self.uncovered]}


class Observation(object):
    """What a call or run did, in NEPO terms."""

    def __init__(self, subject, observer, error):
        self.subject = subject
        self.robot = observer.robot
        self.error = error
        self.actions = observer.actions()
        self.calls = [c.to_json() for c in observer.function_calls]
        self.sensor_reads = observer.sensor_reads()
        self.coverage = Coverage(subject, observer.covered_blocks())
        self.time_ms = self.robot.now

    def actions_of(self, block_type):
        return [a for a in self.actions if a['block'] == block_type]

    def format_actions(self):
        lines = []
        for a in self.actions:
            detail = ', '.join('%s=%r' % (k, v) for k, v in a.items() if k not in ('t', 'block', 'block_id', 'function'))
            where = ' [%s]' % a['function'] if a['function'] else ''
            lines.append('%9.1f ms  %s(%s)%s' % (a['t'], a['block'], detail, where))
        return '\n'.join(lines)


class CallResult(Observation):
    def __init__(self, subject, observer, returned, variables, error):
        super(CallResult, self).__init__(subject, observer, error)
        self._returned = returned
        self.variables = variables

    @property
    def returned(self):
        """the function's return value (NEPO: number, boolean, list); re-raises the NepoError if the call failed"""
        if self.error is not None:
            raise self.error
        return self._returned


class ProgramRun(Observation):
    """status: 'finished', 'time_limit' / 'step_limit' (still running when the budget ran out), or 'error'"""

    def __init__(self, subject, observer, status, variables, error):
        super(ProgramRun, self).__init__(subject, observer, error)
        self.status = status
        self.variables = variables

    finished = property(lambda self: self.status == 'finished')
    running = property(lambda self: self.status in ('time_limit', 'step_limit'))

    def __repr__(self):
        return 'ProgramRun(status=%r, time_ms=%.1f, variables=%r, error=%r)' % (self.status, self.time_ms, self.variables, self.error)


class TestSubject(object):
    __test__ = False  # not a pytest test class

    def __init__(self, bundle):
        if sys.version_info < (3, 11):
            raise RuntimeError('nepotest needs CPython 3.11+ (it maps runtime positions to blocks with code.co_positions())')
        if not bundle.ok:
            raise ConversionError(bundle)
        self.bundle = bundle
        self.nepo = NepoProgram(bundle.xml)
        self.name = bundle.data.get('program_name', 'program')
        self.edprogram = EdProgram(bundle.edpy, filename='<nepo %s>' % self.name, instrument=True)
        self.source_map = SourceMap(bundle.edpy, bundle.source_map)
        self._enclosing = self._compute_enclosing_statements()

    # ------------------------------------------------------------------ construction

    @classmethod
    def from_bundle(cls, path):
        return cls(Bundle.load(path))

    @classmethod
    def from_lab(cls, xml_text, lab='http://localhost:1999', program_name='program'):
        client = lab if isinstance(lab, LabClient) else LabClient(lab)
        return cls(client.convert(xml_text, program_name))

    @classmethod
    def load(cls, program_path, lab=None, bundle=None):
        """program_path: a NEPO export XML. Uses `bundle` (a JSON file) if it exists and matches the XML; otherwise converts
        with the Lab at `lab` (default: $NEPOTEST_LAB or http://localhost:1999) and, if `bundle` is given, saves it there."""
        with open(program_path, encoding='utf-8') as f:
            xml_text = f.read()
        if bundle and os.path.exists(bundle):
            cached = Bundle.load(bundle)
            if cached.matches(xml_text) and (lab is None or not os.environ.get('NEPOTEST_RECONVERT')):
                return cls(cached)
        client = lab if isinstance(lab, LabClient) else LabClient(lab or os.environ.get('NEPOTEST_LAB', 'http://localhost:1999'))
        converted = client.convert(xml_text, os.path.splitext(os.path.basename(program_path))[0])
        if bundle and converted.ok:
            converted.save(bundle)
        return cls(converted)

    # ------------------------------------------------------------------ static information

    def describe(self):
        d = self.nepo.describe()
        d['edpy_lines'] = len(self.bundle.edpy.splitlines())
        d['coverable_blocks'] = len(self.coverable_blocks())
        return d

    def coverable_blocks(self):
        generated = set(b.id for b in self.nepo.generated_blocks())
        return set(b for b in self.source_map.blocks if b in generated and self.source_map.type_of(b) not in ('text_comment',))

    def enclosing_statement(self, block_id):
        return self._enclosing.get(block_id)

    def _compute_enclosing_statements(self):
        spans = []
        for k, (line, end_line, col, end_col) in enumerate(self.edprogram.statements):
            spans.append((self.source_map.offset(line, col), self.source_map.offset(end_line, end_col), k))
        result = {}
        for block_id in self.source_map.blocks:
            s = self.source_map.start(block_id)
            best = None
            for (a, b, k) in spans:
                if a is not None and b is not None and a <= s < b and (best is None or b - a < best[0]):
                    best = (b - a, k)
            if best is not None:
                result[block_id] = best[1]
        return result

    # ------------------------------------------------------------------ running

    def call(self, function, *args, **kwargs):
        """Calls NEPO function `function` with NEPO values, after the program's setup and declarations (its main
        program doesn't run). Options: globals={name: value} (set before the call), world=World(...),
        max_steps=100000, max_time_ms=60000, robot_options={...} (see engine Robot)."""
        world = kwargs.pop('world', None) or World()
        globals_ = kwargs.pop('globals', None) or {}
        max_steps = kwargs.pop('max_steps', 100000)
        max_time_ms = kwargs.pop('max_time_ms', 60000)
        robot = world.build_robot(**kwargs.pop('robot_options', {}))
        if kwargs:
            raise TypeError('unexpected arguments %r' % sorted(kwargs))
        observer = Observer(self, robot)
        session = self.edprogram.load(robot, listeners=[observer])
        for name, value in globals_.items():
            session[name] = value
        returned, error = None, None
        try:
            returned = nepo_value(session.call(function, *args, max_steps=max_steps, max_time_ms=max_time_ms))
        except StepLimitExceeded as e:
            error = NepoError('step_limit', e.message, *self._block_of(e), edpy_line=e.line)
        except EdTestError as e:
            error = self._nepo_error(e)
        return CallResult(self, observer, returned, dict((k, nepo_value(v)) for k, v in session.vars.items()), error)

    def run(self, world=None, max_time_ms=60000, max_steps=2000000, overflow='raise', robot_options=None):
        """Runs the whole program against `world`."""
        robot = (world or World()).build_robot(**(robot_options or {}))
        observer = Observer(self, robot)
        observer.main_ran = True
        error, status, variables = None, 'error', {}
        holder = {}

        class Keep(object):
            def on_prelude_done(self, namespace):
                holder['ns'] = namespace

        try:
            result = self.edprogram.run(robot, max_time_ms=max_time_ms, max_steps=max_steps, overflow=overflow, listeners=[observer, Keep()])
            status, variables = result.status, result.vars
        except EdTestError as e:
            error = self._nepo_error(e)
            if 'ns' in holder:
                variables = self.edprogram._variables(holder['ns'])
        return ProgramRun(self, observer, status, dict((k, nepo_value(v)) for k, v in variables.items()), error)

    def _block_of(self, err):
        """(block_id, block_type, function) of the innermost block at the innermost program position of an error"""
        for pos in reversed(getattr(err, 'positions', []) or []):
            blocks = self.source_map.at_position(pos)
            if blocks:
                return blocks[0], self.source_map.type_of(blocks[0]), self.nepo.function_of(blocks[0])
        return None, None, None

    def _nepo_error(self, err):
        return NepoError(err.kind or 'error', err.message, *self._block_of(err), edpy_line=err.line)

    def check_with_edpy(self):
        """Level 0: does the reference EdPy compiler accept the generated program? (needs EDPY_HOME/EDPY_PYTHON)"""
        from .engine import edpy_check
        return edpy_check.check_source(self.bundle.edpy)

files.nepotest/summary.py:
"""A JSON-able description of a NEPO program for test authors and AI test generators: what the program consists of, and
static hints about what is worth testing (part 2 of the project goal). The hints are heuristics, not proofs.

    {"robot_group": "edison",
     "variables": [{"name", "type", "initial", "block_id"}],
     "functions": [{"name", "params": [{"name", "type"}], "returns", "block_id", "calls", "sensors", "actions"}],
     "main": [<outline node>], "sensors": [...], "actions": [...],
     "test_hints": [{"kind", "block_id", "function", "detail", "suggested"}]}
"""

from .nepo import ACTION_TYPES, FUNCTION_CALL_TYPES, SENSOR_TYPES

COMPARE_SYMBOL = {'EQ': '==', 'NEQ': '!=', 'LT': '<', 'LTE': '<=', 'GT': '>', 'GTE': '>='}
LOOP_TYPES = ('controls_whileUntil', 'controls_repeat_ext', 'robControls_loopForever', 'controls_for', 'controls_forEach')


def _sensor_info(b):
    info = {'block_id': b.id, 'type': b.type}
    for key in ('SENSORPORT', 'MODE', 'SENSORTYPE'):
        if b.fields.get(key):
            info[key.lower()] = b.fields[key]
    return info


def _action_info(b):
    info = {'block_id': b.id, 'type': b.type}
    info.update(dict((k.lower(), v) for k, v in b.fields.items()))
    for name, value in b.values.items():
        if b.type == 'robControls_wait_for':
            break  # its inputs are conditions, shown as "until"
        lit = value.literal()
        info[name.lower()] = lit if lit is not None else '<%s>' % value.type
    return info


def _expr(b):
    """a short text for an expression block (for hints)"""
    if b is None:
        return '?'
    lit = b.literal()
    if lit is not None:
        return repr(lit)
    if b.type == 'variables_get':
        return b.fields.get('VAR', '?')
    if b.type == 'logic_compare':
        return '%s %s %s' % (_expr(b.values.get('A')), COMPARE_SYMBOL.get(b.fields.get('OP'), '?'), _expr(b.values.get('B')))
    if b.type == 'math_arithmetic':
        ops = {'ADD': '+', 'MINUS': '-', 'MULTIPLY': '*', 'DIVIDE': '/', 'POWER': '^'}
        return '(%s %s %s)' % (_expr(b.values.get('A')), ops.get(b.fields.get('OP'), '?'), _expr(b.values.get('B')))
    if b.type in FUNCTION_CALL_TYPES:
        return '%s(...)' % b.mutation.get('name')
    if b.type in SENSOR_TYPES:
        name = b.type.replace('robSensors_', '').replace('_getSample', '')
        return '%s[%s]' % (name, b.fields['SENSORPORT']) if b.fields.get('SENSORPORT') else name
    return '<%s>' % b.type


def _outline(b):
    node = {'block_id': b.id, 'type': b.type}
    if b.type in ACTION_TYPES:
        node.update(_action_info(b))
    if b.type == 'robControls_if' or b.type == 'robControls_ifElse' or b.type == 'controls_whileUntil':
        node['condition'] = _expr(b.values.get('IF0') or b.values.get('BOOL'))
    if b.type == 'robControls_wait_for':
        node['until'] = [_expr(b.values[k]) for k in sorted(b.values) if k.startswith('WAIT')]
    if b.type in FUNCTION_CALL_TYPES:
        node['function'] = b.mutation.get('name')
    body = [_outline(c) for name, seq in sorted(b.statements.items()) for c in seq]
    if body:
        node['body'] = body
    return node


def _hints(program):
    hints = []

    def add(kind, b, detail, suggested=None):
        h = {'kind': kind, 'block_id': b.id, 'function': program.function_of(b.id), 'detail': detail}
        if suggested is not None:
            h['suggested'] = suggested
        hints.append(h)

    for f in program.functions.values():
        add('function', f.block, 'function %s(%s)%s' % (f.name, ', '.join(p for p, _ in f.params),
                                                      ' returns ' + f.returns if f.returns else ''),
            {'call_with': 'boundary values of the comparisons below, 0, negative numbers, and values near +-32767'})
    for b in program.generated_blocks():
        if b.type == 'logic_compare':
            a, c = b.values.get('A'), b.values.get('B')
            for var, const in ((a, c), (c, a)):
                if var is not None and const is not None and const.literal() is not None and var.literal() is None \
                        and isinstance(const.literal(), int):
                    n = const.literal()
                    add('boundary', b, _expr(b), {'values': [n - 1, n, n + 1], 'of': _expr(var)})
        elif b.type == 'math_arithmetic' and b.fields.get('OP') == 'DIVIDE':
            divisor = b.values.get('B')
            if divisor is not None and divisor.literal() is None:
                add('division', b, _expr(b), {'divisor': _expr(divisor), 'values': [0], 'note': 'integer division rounds down'})
            add('integer_division', b, _expr(b), {'note': 'EdPy divides integers: 7 / 2 = 3'})
        elif b.type == 'math_modulo':
            add('division', b, 'remainder', {'divisor': _expr(b.values.get('DIVISOR')), 'values': [0]})
        elif b.type in ('robLists_getIndex', 'robLists_setIndex'):
            at = b.values.get('AT')
            if at is not None and at.literal() is None:
                add('list_index', b, 'list index %s' % _expr(at), {'values': [-1, 0, 'length - 1', 'length']})
        elif b.type == 'robControls_wait_for':
            sensors = [_sensor_info(s) for s in b.walk() if s.type in SENSOR_TYPES]
            add('wait_for_sensor', b, 'waits until ' + ' / '.join(_expr(b.values[k]) for k in sorted(b.values)),
                {'scenarios': ['the event never happens', 'it happens once', 'it happens twice between two reads',
                               'it happens during the setup block (first 250 ms)'], 'sensors': sensors})
        elif b.type in LOOP_TYPES:
            add('loop', b, b.type, {'iterations': [0, 1, 'many'], 'note': 'a loop that never ends leaves the run with status "running"'})
        elif b.type == 'logic_operation':
            right = b.values.get('B')
            if right is not None and any(s.type in SENSOR_TYPES or s.type in FUNCTION_CALL_TYPES for s in right.walk()):
                add('eager_and_or', b, _expr(b), {'note': 'both sides are always evaluated on the Edison; sensors are read (and cleared)'})
        elif b.type in ('robActions_play_tone',):
            add('output', b, 'tone', {'note': 'the buzzer plays 4 x the NEPO frequency'})
    return hints


def describe(program):
    sensors = [dict(_sensor_info(b), function=program.function_of(b.id)) for b in program.generated_blocks() if b.type in SENSOR_TYPES]
    actions = [dict(_action_info(b), function=program.function_of(b.id)) for b in program.generated_blocks() if b.type in ACTION_TYPES]
    functions = []
    for f in program.functions.values():
        blocks = list(f.block.walk())
        functions.append({
            'name': f.name, 'block_id': f.block.id, 'returns': f.returns,
            'params': [{'name': n, 'type': t} for n, t in f.params],
            'calls': sorted(set(b.mutation.get('name') for b in blocks if b.type in FUNCTION_CALL_TYPES)),
            'sensors': sorted(set(b.type for b in blocks if b.type in SENSOR_TYPES)),
            'actions': sorted(set(b.type for b in blocks if b.type in ACTION_TYPES)),
        })
    return {
        'robot_group': program.robot_group,
        'variables': [{'name': v.name, 'type': v.type, 'initial': v.initial, 'block_id': v.block.id} for v in program.variables],
        'functions': functions,
        'main': [_outline(b) for b in program.main if b.generated],
        'sensors': sensors,
        'actions': actions,
        'test_hints': _hints(program),
    }

files.nepotest/world.py:
"""What happens around the robot during a test, in NEPO terms (the ports and values of the Edison's sensor blocks).

    World().clap(at=1000).key('PLAY', at=1500).obstacle('FRONT', start=2000, end=2500).light('LLIGHT', 45).line('black', at=3000)

Times are virtual milliseconds from program start. Every generated program first runs a fixed setup block (about 254 ms)
that discards a clap in its first millisecond. JSON form (used in test files), one object per event:

    {"event": "clap", "at": 1000}                          {"event": "key", "port": "PLAY", "at": 1500}
    {"event": "obstacle", "port": "FRONT", "from": 2000, "to": 2500}
    {"event": "light", "port": "LLIGHT", "value": 45, "at": 0}      value as the NEPO light block reports it
    {"event": "line", "color": "black", "at": 3000}        {"event": "remote", "code": 3, "at": 100}
    {"event": "ir_message", "value": 42, "at": 100}         {"event": "strain", "from": 0, "to": 500}
"""

from .engine import Robot

KEY_PORTS = {'PLAY': 'triangle', 'REC': 'round'}
OBSTACLE_PORTS = {'FRONT': 'ahead', 'LEFT': 'left', 'RIGHT': 'right'}
LIGHT_PORTS = {'LLIGHT': 'left', 'RLIGHT': 'right', 'LINETRACKER': 'tracker'}
EVENTS = ('clap', 'key', 'obstacle', 'light', 'line', 'remote', 'ir_message', 'strain')


class World(object):
    def __init__(self, events=None):
        self.events = []
        for e in events or []:
            self.add(e)

    def add(self, event):
        e = dict(event)
        kind = e.get('event')
        if kind not in EVENTS:
            raise ValueError('unknown world event %r (known: %s)' % (kind, ', '.join(EVENTS)))
        if kind == 'key' and e.get('port') not in KEY_PORTS:
            raise ValueError('key port must be PLAY or REC')
        if kind == 'obstacle' and e.get('port') not in OBSTACLE_PORTS:
            raise ValueError('obstacle port must be FRONT, LEFT or RIGHT')
        if kind == 'light' and e.get('port') not in LIGHT_PORTS:
            raise ValueError('light port must be LLIGHT, RLIGHT or LINETRACKER')
        if kind == 'line' and e.get('color') not in ('black', 'white'):
            raise ValueError("line color must be 'black' or 'white'")
        self.events.append(e)
        return self

    def clap(self, at):
        return self.add({'event': 'clap', 'at': at})

    def key(self, port, at):
        return self.add({'event': 'key', 'port': port, 'at': at})

    def obstacle(self, port, start=0, end=None):
        return self.add({'event': 'obstacle', 'port': port, 'from': start, 'to': end})

    def light(self, port, value, at=0):
        return self.add({'event': 'light', 'port': port, 'value': value, 'at': at})

    def line(self, color, at=0):
        return self.add({'event': 'line', 'color': color, 'at': at})

    def remote(self, code, at):
        return self.add({'event': 'remote', 'code': code, 'at': at})

    def ir_message(self, value, at):
        return self.add({'event': 'ir_message', 'value': value, 'at': at})

    def strain(self, start=0, end=None):
        return self.add({'event': 'strain', 'from': start, 'to': end})

    def to_json(self):
        return [dict(e) for e in self.events]

    def build_robot(self, **robot_options):
        """the engine's virtual robot with these events scheduled"""
        robot = Robot(**robot_options)
        for e in self.events:
            kind = e['event']
            if kind == 'clap':
                robot.clap(at=e['at'])
            elif kind == 'key':
                robot.press(KEY_PORTS[e['port']], at=e['at'])
            elif kind == 'obstacle':
                robot.obstacle(OBSTACLE_PORTS[e['port']], start=e.get('from', 0), end=e.get('to'))
            elif kind == 'light':
                # generated code reads `Ed.Read...() / 10`, so a raw level of value * 10 is reported as value
                robot.light(at=e.get('at', 0), **{LIGHT_PORTS[e['port']]: int(e['value']) * 10})
            elif kind == 'line':
                robot.surface(e['color'], at=e.get('at', 0))
            elif kind == 'remote':
                robot.remote(e['code'], at=e['at'])
            elif kind == 'ir_message':
                robot.ir_data(e['value'], at=e['at'])
            elif kind == 'strain':
                robot.strain(start=e.get('from', 0), end=e.get('to'))
        return robot
